(function () {
'use strict';
document.addEventListener('error', function (e) {
var t = e.target;
if (!t || t.tagName !== 'IMG') return;
var thumb = t.closest('.article-card-thumb');
if (!thumb) return;
var card = thumb.closest('.article-card');
if (card) card.classList.add('no-cover');
thumb.remove();
}, true);
})();